import json
import re
from collections import defaultdict

# Parse TSL specification

def parse_tsl(tsl_text):
    categories = {}
    current_category = None
    for line in tsl_text.strip().split('\n'):
        line = line.strip()
        if not line:
            continue
        # Check if it's a category header
        match = re.match(r'^\s*([A-Z]+):', line)
        if match:
            current_category = match.group(1)
            categories[current_category] = []
            continue
        # Otherwise it's a choice line
        if current_category is None:
            continue
        parts = line.split(':')
        if len(parts) < 2:
            continue
        choice_desc = parts[0].strip()
        annotations = parts[1].strip().split()

        properties = []  # list of property names
        if_conditions = []  # list of condition strings like "X and Y", "X or Y", "X"

        for ann in annotations:
            ann = ann.strip()
            if ann.startswith('[property ') and ann.endswith(']'):
                prop_name = ann[9:-1]
                properties.append(prop_name)
            elif ann.startswith('[if ') and ann.endswith(']'):
                cond_str = ann[4:-1]
                if_conditions.append(cond_str)

        categories[current_category].append({
            'description': choice_desc,
            'properties': properties,
            'if_conditions': if_conditions
        })
    return categories

